//! Compares `BilstmPosModel`, `BilstmPosTagger`, `BilstmPosTrainer`, `CrfScorer`,
//! `FeedforwardPosContext`, `FeedforwardPosModel`, `FeedforwardPosTagger`,
//! `FeedforwardPosTrainer`, and `JavaRng` against the JVM binary model fixtures
//! and test vectors in `tests/vectors/`, generated by `java/NeuralPosVectors.java`
//! on the pinned JDK 21 image against OpenNLP commit
//! `cdf33c653d5d61d5af7d37ffee189a83bd8392ea`.

use std::collections::BTreeMap;

use turbo_analysis::Annotator;
use turbo_maxent::sha256;
use turbo_postag::neural::{
    BilstmPosModel, BilstmPosTagger, BilstmPosTrainer, BilstmSettings, CrfScorer, FeedforwardPosContext,
    FeedforwardPosModel, FeedforwardPosTagger, FeedforwardPosTrainer, FeedforwardSettings, JavaRng, PosSample,
};

const VECTORS: &str = include_str!("vectors/neural_postag.tsv");
const BILSTM_CRF_BIN: &[u8] = include_bytes!("vectors/bilstm_crf.bin");
const BILSTM_SOFTMAX_BIN: &[u8] = include_bytes!("vectors/bilstm_softmax.bin");
const FF_V1_BIN: &[u8] = include_bytes!("vectors/feedforward_v1.bin");
const FF_V2_BIN: &[u8] = include_bytes!("vectors/feedforward_v2.bin");

fn parse_hex_f64s(s: &str) -> Vec<f64> {
    if s.is_empty() {
        return Vec::new();
    }
    s.split(',').map(|h| f64::from_bits(u64::from_str_radix(h, 16).unwrap())).collect()
}

fn parse_hex_matrix(s: &str) -> Vec<Vec<f64>> {
    if s.is_empty() {
        return Vec::new();
    }
    s.split(';').map(parse_hex_f64s).collect()
}

fn parse_ints(s: &str) -> Vec<isize> {
    if s.is_empty() || s == "-" {
        return Vec::new();
    }
    s.split(',').map(|x| x.parse::<isize>().unwrap()).collect()
}

fn evaluation_sentences() -> Vec<Vec<&'static str>> {
    vec![
        vec!["The", "brown", "fox", "jumps", "quickly", "."],
        vec!["A", "curious", "cat", "runs", "in", "London", "."],
        vec!["42", "dogs", "sleep", "at", "caf\u{00E9}", "tables", "."],
        vec!["Paris"],
    ]
}

fn training_corpus() -> Vec<PosSample> {
    vec![
        PosSample::new(
            ["The", "quick", "brown", "fox", "jumps", "over", "the", "lazy", "dog", "."],
            ["DET", "ADJ", "ADJ", "NOUN", "VERB", "ADP", "DET", "ADJ", "NOUN", "PUNCT"],
        )
        .unwrap(),
        PosSample::new(
            ["A", "fast", "fox", "runs", "quickly", "in", "Paris", "."],
            ["DET", "ADJ", "NOUN", "VERB", "ADV", "ADP", "PROPN", "PUNCT"],
        )
        .unwrap(),
        PosSample::new(
            ["Dogs", "and", "cats", "sleep", "quietly", "under", "25", "trees", "."],
            ["NOUN", "CCONJ", "NOUN", "VERB", "ADV", "ADP", "NUM", "NOUN", "PUNCT"],
        )
        .unwrap(),
        PosSample::new(
            ["Paris", "welcomes", "happy", "travelers", "at", "caf\u{00E9}", "tables", "."],
            ["PROPN", "VERB", "ADJ", "NOUN", "ADP", "NOUN", "NOUN", "PUNCT"],
        )
        .unwrap(),
    ]
}

fn pretrained_table() -> (BTreeMap<String, Vec<f32>>, Vec<String>) {
    let entries: &[(&str, [f32; 4])] = &[
        ("the", [0.25, -0.50, 0.75, 0.125]),
        ("fox", [0.80, 0.10, -0.30, 0.40]),
        ("dog", [0.75, 0.15, -0.25, 0.35]),
        ("jumps", [-0.40, 0.90, 0.20, -0.10]),
        ("runs", [-0.35, 0.85, 0.15, -0.05]),
        ("paris", [0.10, -0.20, 0.60, 0.95]),
        ("london", [0.12, -0.18, 0.58, 0.92]),
    ];
    let mut map = BTreeMap::new();
    let mut vocab = Vec::new();
    for &(k, v) in entries {
        map.insert(k.to_owned(), v.to_vec());
        vocab.push(k.to_owned());
    }
    (map, vocab)
}

fn assert_f64_slice_close(actual: &[f64], expected: &[f64], tol: f64, ctx: &str) {
    assert_eq!(actual.len(), expected.len(), "{ctx}: length mismatch");
    for (i, (&a, &e)) in actual.iter().zip(expected.iter()).enumerate() {
        if a.to_bits() == e.to_bits() {
            continue;
        }
        let diff = (a - e).abs();
        assert!(
            diff <= tol,
            "{ctx}[{i}]: actual={a} ({:016x}) != expected={e} ({:016x}), diff={diff} > tol={tol}",
            a.to_bits(),
            e.to_bits()
        );
    }
}

#[test]
fn java_rng_next_gaussian_matches_jdk21_bits() {
    let mut checked = 0usize;
    for raw in VECTORS.lines() {
        let line = raw.trim_end_matches('\r');
        if !line.starts_with("rng_gaussian\t") {
            continue;
        }
        let cols: Vec<&str> = line.split('\t').collect();
        let seed: i64 = cols[1].parse().unwrap();
        let expected = parse_hex_f64s(cols[2]);
        let mut rng = JavaRng::new(seed);
        for (i, &exp) in expected.iter().enumerate() {
            let actual = rng.next_gaussian();
            assert_eq!(
                actual.to_bits(),
                exp.to_bits(),
                "rng_gaussian seed={seed} index={i}: {:016x} != {:016x}",
                actual.to_bits(),
                exp.to_bits()
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 6);
}

#[test]
fn bilstm_models_and_tagger_match_jvm_goldens() {
    let models = [("bilstm_crf", BILSTM_CRF_BIN), ("bilstm_softmax", BILSTM_SOFTMAX_BIN)];
    let sentences = evaluation_sentences();

    for (model_id, raw_bytes) in models {
        let model = BilstmPosModel::load(raw_bytes).unwrap();
        let mut reserialized = Vec::new();
        model.serialize(&mut reserialized).unwrap();
        assert_eq!(reserialized, raw_bytes, "{model_id}: serialized bytes must match JVM binary stream byte-for-byte");

        let tagger = BilstmPosTagger::new(model.clone());
        let model_ref = Annotator::model(&tagger).expect("BilstmPosTagger must report a ModelRef");
        assert_eq!(model_ref.id, "opennlp:BilstmPOSModel");
        assert_eq!(model_ref.sha256, sha256(raw_bytes).to_hex());

        for raw in VECTORS.lines() {
            let line = raw.trim_end_matches('\r');
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let cols: Vec<&str> = line.split('\t').collect();
            if cols.len() < 3 || cols[1] != model_id {
                continue;
            }
            match cols[0] {
                "bilstm_meta" => match cols[2] {
                    "sha256" => {
                        assert_eq!(model_ref.sha256, cols[3]);
                        assert_eq!(raw_bytes.len(), cols[4].parse::<usize>().unwrap());
                    }
                    "tags" => {
                        let exp_tags: Vec<&str> = cols[3].split(',').collect();
                        assert_eq!(model.tags(), &exp_tags);
                    }
                    "is_crf" => {
                        assert_eq!(model.is_crf(), cols[3].parse::<bool>().unwrap());
                    }
                    _ => {}
                },
                "bilstm_crf_params" => match cols[2] {
                    "start" => {
                        let exp = parse_hex_f64s(cols[3]);
                        assert_f64_slice_close(model.start_weights().unwrap(), &exp, 0.0, "start_weights");
                    }
                    "end" => {
                        let exp = parse_hex_f64s(cols[3]);
                        assert_f64_slice_close(model.end_weights().unwrap(), &exp, 0.0, "end_weights");
                    }
                    "transitions" => {
                        let exp = parse_hex_matrix(cols[3]);
                        let tr = model.transition_weights().unwrap();
                        for (r, row) in exp.iter().enumerate() {
                            assert_f64_slice_close(&tr[r], row, 0.0, "transition_weights");
                        }
                    }
                    _ => {}
                },
                "bilstm_rep" => {
                    let s_idx: usize = cols[2].parse().unwrap();
                    let t_idx: usize = cols[3].parse().unwrap();
                    let exp = parse_hex_f64s(cols[4]);
                    let rep = model.word_representation(sentences[s_idx][t_idx]).unwrap();
                    assert_f64_slice_close(&rep, &exp, 1e-15, &format!("{model_id} rep[{s_idx}][{t_idx}]"));
                }
                "bilstm_emissions" => {
                    let s_idx: usize = cols[2].parse().unwrap();
                    let exp = parse_hex_matrix(cols[3]);
                    let emissions = model.score(&sentences[s_idx]).unwrap();
                    assert_eq!(emissions.len(), exp.len());
                    for (t, row) in exp.iter().enumerate() {
                        assert_f64_slice_close(
                            &emissions[t],
                            row,
                            1e-14,
                            &format!("{model_id} emissions[{s_idx}][{t}]"),
                        );
                    }
                }
                "bilstm_viterbi" => {
                    let s_idx: usize = cols[2].parse().unwrap();
                    let exp: Vec<usize> = parse_ints(cols[3]).into_iter().map(|x| x as usize).collect();
                    let emissions = model.score(&sentences[s_idx]).unwrap();
                    let viterbi = CrfScorer::viterbi(
                        &emissions,
                        model.transition_weights().unwrap(),
                        model.start_weights().unwrap(),
                        model.end_weights().unwrap(),
                    )
                    .unwrap();
                    assert_eq!(viterbi, exp, "{model_id} viterbi[{s_idx}]");
                }
                "bilstm_marginals" => {
                    let s_idx: usize = cols[2].parse().unwrap();
                    let exp = parse_hex_matrix(cols[3]);
                    // On the JVM's own emissions the CRF gives the JVM's
                    // marginals bit for bit; the tolerance below only covers
                    // the emissions (see the BiLSTM model documentation).
                    let jvm_emissions = VECTORS
                        .lines()
                        .map(|l| l.split('\t').collect::<Vec<_>>())
                        .find(|c| c[0] == "bilstm_emissions" && c[1] == model_id && c[2] == cols[2])
                        .map(|c| parse_hex_matrix(c[3]))
                        .expect("emissions row for the marginals row");
                    let from_jvm = CrfScorer::marginals(
                        &jvm_emissions,
                        model.transition_weights().unwrap(),
                        model.start_weights().unwrap(),
                        model.end_weights().unwrap(),
                    )
                    .unwrap();
                    for (t, row) in exp.iter().enumerate() {
                        assert_f64_slice_close(
                            &from_jvm[t],
                            row,
                            0.0,
                            &format!("{model_id} marginals of JVM emissions[{s_idx}][{t}]"),
                        );
                    }
                    let emissions = model.score(&sentences[s_idx]).unwrap();
                    let marginals = CrfScorer::marginals(
                        &emissions,
                        model.transition_weights().unwrap(),
                        model.start_weights().unwrap(),
                        model.end_weights().unwrap(),
                    )
                    .unwrap();
                    assert_eq!(marginals.len(), exp.len());
                    for (t, row) in exp.iter().enumerate() {
                        assert_f64_slice_close(
                            &marginals[t],
                            row,
                            1e-14,
                            &format!("{model_id} marginals[{s_idx}][{t}]"),
                        );
                    }
                }
                "bilstm_tagger" => {
                    let s_idx: usize = cols[2].parse().unwrap();
                    let exp_tags: Vec<&str> = cols[3].split(',').collect();
                    let exp_seq_outcomes: Vec<&str> = cols[4].split(',').collect();
                    let exp_probs = parse_hex_f64s(cols[5]);
                    let exp_score = parse_hex_f64s(cols[6])[0];

                    let tags = tagger.tag(&sentences[s_idx]).unwrap();
                    assert_eq!(tags, exp_tags, "{model_id} tag[{s_idx}]");
                    let seq = &tagger.top_k_sequences(&sentences[s_idx]).unwrap()[0];
                    assert_eq!(seq.outcomes(), &exp_seq_outcomes);
                    assert_f64_slice_close(seq.probs(), &exp_probs, 1e-14, &format!("{model_id} probs[{s_idx}]"));
                    assert!((seq.score() - exp_score).abs() <= 1e-13, "{model_id} score[{s_idx}]");
                }
                _ => {}
            }
        }
    }
}

#[test]
fn feedforward_models_and_tagger_match_jvm_goldens_bit_for_bit() {
    let models = [("feedforward_v1", FF_V1_BIN), ("feedforward_v2", FF_V2_BIN)];
    let sentences = evaluation_sentences();

    for (model_id, raw_bytes) in models {
        let model = FeedforwardPosModel::load(raw_bytes).unwrap();
        let mut reserialized = Vec::new();
        model.serialize(&mut reserialized).unwrap();
        assert_eq!(reserialized, raw_bytes, "{model_id}: serialized bytes must match JVM binary stream byte-for-byte");

        for raw in VECTORS.lines() {
            let line = raw.trim_end_matches('\r');
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let cols: Vec<&str> = line.split('\t').collect();
            if cols.len() < 3 || cols[1] != model_id {
                continue;
            }
            match cols[0] {
                "ff_meta" => match cols[2] {
                    "sha256" => {
                        assert_eq!(model.model_ref().sha256, cols[3]);
                        assert_eq!(raw_bytes.len(), cols[4].parse::<usize>().unwrap());
                    }
                    "tags" => {
                        let exp_tags: Vec<&str> = cols[3].split(',').collect();
                        assert_eq!(model.tags(), &exp_tags);
                    }
                    "pretrained" => {
                        assert_eq!(model.uses_pretrained_vectors(), cols[3].parse::<bool>().unwrap());
                    }
                    _ => {}
                },
                "ff_step_uncached" => {
                    let s_idx: usize = cols[2].parse().unwrap();
                    let pos: usize = cols[3].parse().unwrap();
                    let exp_f_ids: Vec<usize> = parse_ints(cols[4]).into_iter().map(|x| x as usize).collect();
                    let exp_p_rows = parse_ints(cols[5]);
                    let exp_scores = parse_hex_f64s(cols[6]);

                    // Reconstruct prev and prev_prev by running up to `pos`.
                    let sent = &sentences[s_idx];
                    let mut prev: Option<String> = None;
                    let mut prev_prev: Option<String> = None;
                    for i in 0..=pos {
                        let ctx = FeedforwardPosContext::extract(sent, i, prev.as_deref(), prev_prev.as_deref());
                        let f_ids = model.feature_ids(&ctx);
                        let p_rows = model.pretrained_rows(sent, i);
                        let scores = model.score_with_pretrained(&f_ids, p_rows.as_ref().map(|r| &r[..])).unwrap();
                        if i == pos {
                            assert_eq!(f_ids.as_slice(), exp_f_ids.as_slice(), "{model_id} f_ids[{s_idx}][{pos}]");
                            if exp_p_rows.is_empty() {
                                assert!(p_rows.is_none());
                            } else {
                                assert_eq!(p_rows.unwrap().as_slice(), exp_p_rows.as_slice());
                            }
                            assert_f64_slice_close(
                                &scores,
                                &exp_scores,
                                0.0,
                                &format!("{model_id} uncached scores[{s_idx}][{pos}]"),
                            );
                        }
                        let mut best = 0usize;
                        for o in 1..scores.len() {
                            if scores[o] > scores[best] {
                                best = o;
                            }
                        }
                        prev_prev = prev;
                        prev = Some(model.tags()[best].clone());
                    }
                }
                _ => {}
            }
        }

        // Now construct FeedforwardPosTagger (enables contribution cache) and check cached scores + tagger output.
        let tagger = FeedforwardPosTagger::new(model.clone());
        let model_ref = Annotator::model(&tagger).expect("FeedforwardPosTagger must report a ModelRef");
        assert_eq!(model_ref.id, "opennlp:FeedforwardPOSModel");
        assert_eq!(model_ref.sha256, sha256(raw_bytes).to_hex());

        for raw in VECTORS.lines() {
            let line = raw.trim_end_matches('\r');
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let cols: Vec<&str> = line.split('\t').collect();
            if cols.len() < 3 || cols[1] != model_id {
                continue;
            }
            match cols[0] {
                "ff_step_cached" => {
                    let s_idx: usize = cols[2].parse().unwrap();
                    let pos: usize = cols[3].parse().unwrap();
                    let exp_scores = parse_hex_f64s(cols[4]);

                    let sent = &sentences[s_idx];
                    let mut prev: Option<String> = None;
                    let mut prev_prev: Option<String> = None;
                    for i in 0..=pos {
                        let ctx = FeedforwardPosContext::extract(sent, i, prev.as_deref(), prev_prev.as_deref());
                        let f_ids = tagger.model().feature_ids(&ctx);
                        let p_rows = tagger.model().pretrained_rows(sent, i);
                        let scores =
                            tagger.model().score_with_pretrained(&f_ids, p_rows.as_ref().map(|r| &r[..])).unwrap();
                        if i == pos {
                            assert_f64_slice_close(
                                &scores,
                                &exp_scores,
                                0.0,
                                &format!("{model_id} cached scores[{s_idx}][{pos}]"),
                            );
                        }
                        let mut best = 0usize;
                        for o in 1..scores.len() {
                            if scores[o] > scores[best] {
                                best = o;
                            }
                        }
                        prev_prev = prev;
                        prev = Some(tagger.model().tags()[best].clone());
                    }
                }
                "ff_tagger" => {
                    let s_idx: usize = cols[2].parse().unwrap();
                    let exp_tags: Vec<&str> = cols[3].split(',').collect();
                    let exp_seq_outcomes: Vec<&str> = cols[4].split(',').collect();
                    let exp_probs = parse_hex_f64s(cols[5]);
                    let exp_score = parse_hex_f64s(cols[6])[0];

                    let tags = tagger.tag(&sentences[s_idx]).unwrap();
                    assert_eq!(tags, exp_tags, "{model_id} tag[{s_idx}]");
                    let seq = &tagger.top_k_sequences(&sentences[s_idx]).unwrap()[0];
                    assert_eq!(seq.outcomes(), &exp_seq_outcomes);
                    assert_f64_slice_close(seq.probs(), &exp_probs, 0.0, &format!("{model_id} probs[{s_idx}]"));
                    assert_eq!(seq.score().to_bits(), exp_score.to_bits(), "{model_id} score[{s_idx}]");
                }
                _ => {}
            }
        }
    }
}

#[test]
fn trainers_match_jvm_trained_models() {
    let corpus = training_corpus();
    let (pretrained_map, pretrained_vocab) = pretrained_table();
    let lookup = |k: &str| pretrained_map.get(k).cloned();

    let ff_v1_settings = FeedforwardSettings::new(6, 8, 3, 4, 0.05, 1e-5, 0.1, 1, 1, 42).unwrap();
    let ff_v1 = FeedforwardPosTrainer::train(&corpus, ff_v1_settings).unwrap();
    let mut ff_v1_bytes = Vec::new();
    ff_v1.serialize(&mut ff_v1_bytes).unwrap();
    assert_eq!(
        ff_v1_bytes, FF_V1_BIN,
        "Rust-trained FeedforwardPosModel (v1) must match JVM-trained binary byte-for-byte"
    );

    let ff_v2_settings = FeedforwardSettings::new(6, 8, 3, 4, 0.05, 1e-5, 0.0, 1, 1, 99).unwrap();
    let ff_v2 = FeedforwardPosTrainer::train_with_lexicon(&corpus, ff_v2_settings, lookup, &pretrained_vocab).unwrap();
    let mut ff_v2_bytes = Vec::new();
    ff_v2.serialize(&mut ff_v2_bytes).unwrap();
    assert_eq!(
        ff_v2_bytes, FF_V2_BIN,
        "Rust-trained FeedforwardPosModel (v2) must match JVM-trained binary byte-for-byte"
    );

    let bilstm_softmax_settings = BilstmSettings::new(
        6, 4, 3, 6, 3, 2, 0.05, 5.0, 0.0, 1, 12, 77, 1, 0.0, 0, false, 1, 0.0, 0.0, 0.0, 0.0, false,
    )
    .unwrap();
    let bilstm_softmax = BilstmPosTrainer::train(&corpus, bilstm_softmax_settings).unwrap();
    let jvm_bilstm_softmax = BilstmPosModel::load(BILSTM_SOFTMAX_BIN).unwrap();
    for sent in evaluation_sentences() {
        let rust_scores = bilstm_softmax.score(&sent).unwrap();
        let jvm_scores = jvm_bilstm_softmax.score(&sent).unwrap();
        for (t, (r_row, j_row)) in rust_scores.iter().zip(jvm_scores.iter()).enumerate() {
            assert_f64_slice_close(r_row, j_row, 1e-12, &format!("trained bilstm_softmax emissions[{t}]"));
        }
    }

    let bilstm_crf_settings =
        BilstmSettings::new(6, 4, 3, 6, 3, 2, 0.05, 5.0, 0.1, 1, 12, 42, 1, 0.1, 2, true, 2, 0.1, 0.1, 0.2, 0.0, true)
            .unwrap();
    let bilstm_crf =
        BilstmPosTrainer::train_with_vectors(&corpus, bilstm_crf_settings, Some(lookup), Some(&pretrained_vocab), None)
            .unwrap();
    let jvm_bilstm_crf = BilstmPosModel::load(BILSTM_CRF_BIN).unwrap();
    for sent in evaluation_sentences() {
        let rust_scores = bilstm_crf.score(&sent).unwrap();
        let jvm_scores = jvm_bilstm_crf.score(&sent).unwrap();
        for (t, (r_row, j_row)) in rust_scores.iter().zip(jvm_scores.iter()).enumerate() {
            assert_f64_slice_close(r_row, j_row, 1e-12, &format!("trained bilstm_crf emissions[{t}]"));
        }
    }
}
